# app.R — Split-normal (mean/median/mode) — OUP light theme, ShinyLive ready
library(shiny)
library(bslib)

# ----- split-normal helpers (no extra packages) -----
dsplitnorm <- function(x, mu, sL, sR) {
  cst <- sqrt(2 / pi) / (sL + sR)
  y <- numeric(length(x))
  left <- x <= mu
  y[left]  <- cst * exp(-0.5 * ((x[left]  - mu) / sL)^2)
  y[!left] <- cst * exp(-0.5 * ((x[!left] - mu) / sR)^2)
  y
}

mean_splitnorm <- function(mu, sL, sR) {
  mu + sqrt(2 / pi) * (sR - sL)
}

map_params_simple <- function(m, med, mu, floor_sigma = 3, width_base = 6, c_med = 4) {
  D <- (m - mu) / sqrt(2 / pi)
  w_raw <- 0.5 + 0.5 * tanh((mu - med) / c_med)
  w <- min(max(w_raw, 0.05), 0.95)
  sep <- mean(abs(c(m - mu, med - mu, m - med)))
  T_core <- width_base + 2 * sep
  sL0 <- w * T_core - D / 2
  sR0 <- (1 - w) * T_core + D / 2
  bump <- max(0, floor_sigma - min(sL0, sR0))
  sL <- max(sL0 + bump, 1e-3)
  sR <- max(sR0 + bump, 1e-3)
  list(mu = mu, sL = sL, sR = sR)
}

# ----- OUP theme tokens -----
OUP_BACKGROUND <- "#DFDFDF"
OUP_VALUE_BOX  <- "#CECECE"
OUP_BORDER     <- "#8C8C8C"

OUP_RED        <- "#8A1E00"
OUP_BROWN      <- "#BE5A16"
OUP_ORANGE     <- "#E57726"

OUP_TRACK_GREY <- "#AFAFAF"
OUP_TEXT       <- "#000000"

OUP_MEDIAN     <- "#5F5F5F"
OUP_PERCENTILE <- "#2E6F95"

MEAN_COLOUR   <- OUP_ORANGE
MEDIAN_COLOUR <- OUP_MEDIAN
MODE_COLOUR   <- OUP_PERCENTILE

oup_theme <- bs_theme(
  version = 5,
  bg = OUP_BACKGROUND,
  fg = OUP_TEXT,
  primary = OUP_BROWN,
  secondary = OUP_VALUE_BOX
) |>
  bs_add_rules("
    :root{
      --bs-body-font-family: 'Lexend', system-ui, -apple-system, Segoe UI, Roboto, 'Helvetica Neue', Arial, sans-serif;
      --bs-font-monospace: 'Recursive', ui-monospace, SFMono-Regular, Menlo, Consolas, 'Liberation Mono', monospace;
    }
  ") |>
  bs_add_rules(paste0("
    html{
      height:100% !important;
      min-height:100% !important;
      overflow-y:scroll !important;
      overflow-x:hidden !important;
    }

    body{
      position:static !important;
      height:auto !important;
      min-height:100% !important;
      max-height:none !important;
      overflow:visible !important;
      touch-action:pan-y !important;
    }

    .container-fluid{
      max-width:1100px;
      padding-top:calc(16px + env(safe-area-inset-top));
      padding-bottom:32px;
      overflow:visible !important;
    }

    .shiny-input-container{ margin-bottom:10px; }

    .no-stack{ display:flex; gap:16px; align-items:flex-start; }
    .no-stack .left{ flex:0 0 320px; min-width:260px; }
    .no-stack .right{ flex:1 1 auto; min-width:0; }

    #plotBox{
      background:", OUP_BACKGROUND, " !important;
      border:2px solid ", OUP_BORDER, " !important;
      padding:12px;
      border-radius:.6rem;
      box-shadow:none;
    }

    .form-control, .form-select, .selectize-input{
      background-color:", OUP_VALUE_BOX, " !important;
      color:", OUP_TEXT, " !important;
      border:2px solid ", OUP_BORDER, " !important;
      box-shadow:none !important;
    }

    .form-control:focus, .form-select:focus, .selectize-input.focus{
      border-color:", OUP_BROWN, " !important;
      outline:0 !important;
      box-shadow:0 0 0 .15rem rgba(190,90,22,.25) !important;
    }

    .btn, .btn-default, .action-button{
      background:", OUP_VALUE_BOX, " !important;
      border:2px solid ", OUP_MEDIAN, " !important;
      color:", OUP_TEXT, " !important;
      box-shadow:none !important;
      font-weight:600;
    }

    .btn:hover, .btn:focus, .btn:active,
    .action-button:hover, .action-button:focus, .action-button:active{
      background:", OUP_VALUE_BOX, " !important;
      border-color:", OUP_BROWN, " !important;
      color:", OUP_TEXT, " !important;
      box-shadow:0 0 0 .15rem rgba(190,90,22,.22) !important;
    }

    .irs--shiny .irs-line{
      background:", OUP_TRACK_GREY, " !important;
      border-color:", OUP_BORDER, " !important;
    }

    .irs--shiny .irs-bar,
    .irs--shiny .irs-bar-edge{
      background:", OUP_ORANGE, " !important;
      border-color:", OUP_ORANGE, " !important;
    }

    .irs--shiny .irs-slider,
    .irs--shiny .irs-handle,
    .irs--shiny .irs-handle > i:first-child{
      background:", OUP_VALUE_BOX, " !important;
      border-color:", OUP_BORDER, " !important;
    }

    .irs--shiny .irs-single,
    .irs--shiny .irs-from,
    .irs--shiny .irs-to{
      background:", OUP_VALUE_BOX, " !important;
      color:", OUP_TEXT, " !important;
      border:1px solid ", OUP_BORDER, " !important;
      box-shadow:none !important;
    }

    .irs--shiny .irs-min,
    .irs--shiny .irs-max,
    .irs--shiny .irs-grid-text{
      color:", OUP_TEXT, " !important;
    }

    .legend-dot{
      display:inline-block;
      width:14px;
      height:14px;
      border-radius:7px;
      margin-right:6px;
    }

    .legend-item{ margin-bottom:6px; }
    .sidebar-title{ margin-top:8px; font-weight:600; }

    @media (max-width:576px){
      .no-stack{ flex-direction:column; gap:12px; }
      .no-stack .left, .no-stack .right{
        flex:1 1 100%;
        min-width:0;
        width:100%;
      }
      .no-stack .left .shiny-input-container .control-label{ margin-top:12px; }
      .no-stack .left .shiny-input-container:first-of-type .control-label{ margin-top:8px; }
      .container-fluid{ padding-left:12px; padding-right:12px; }
    }
  "))

ui <- page_fluid(
  theme = oup_theme,

  tags$head(
    tags$link(rel = "preconnect", href = "https://fonts.googleapis.com"),
    tags$link(rel = "preconnect", href = "https://fonts.gstatic.com", crossorigin = "anonymous"),
    tags$link(
      href = "https://fonts.googleapis.com/css2?family=Lexend:wght@300;400;500&family=Recursive:wght,MONO@400,1&display=swap",
      rel = "stylesheet"
    ),
    tags$script(src = "https://cdn.jsdelivr.net/npm/iframe-resizer/js/iframeResizer.contentWindow.min.js"),
    tags$script(HTML("
      document.addEventListener('shiny:idle', function(){
        if (window.parentIFrame && window.parentIFrame.size) {
          window.parentIFrame.size();
        }
      });
    "))
  ),

  # Dynamic-height helpers
  tags$head(
    tags$style(HTML("#plot img{display:block;width:100%;height:auto!important;}")),
    tags$script(HTML("
      (function () {
        function send() {
          if (!window.Shiny) return;
          Shiny.setInputValue('vh_px', window.innerHeight, {priority:'event'});
          Shiny.setInputValue('resizeTick', Date.now(), {priority:'event'});
        }
        window.addEventListener('load', send, {once:true});
        document.addEventListener('shiny:connected', send);
        window.addEventListener('resize', send);
        window.addEventListener('orientationchange', send);
      })();
    ")),
    tags$script(HTML("
      Shiny.addCustomMessageHandler('setSplitHeight', function(px){
        var el = document.getElementById('plot');
        if (el) el.style.height = String(px) + 'px';
      });
    "))
  ),

  div(
    class = "no-stack",

    div(
      class = "left",
      sliderInput("mean", "Mean", min = -20, max = 20, value = 0, step = 0.1),
      sliderInput("median", "Median", min = -20, max = 20, value = 0, step = 0.1),
      sliderInput("mode", "Mode (peak)", min = -20, max = 20, value = 0, step = 0.1),

      div(class = "sidebar-title", "Colour key"),
      div(
        class = "legend-item",
        span(class = "legend-dot", style = paste0("background:", MEAN_COLOUR)),
        "Mean"
      ),
      div(
        class = "legend-item",
        span(class = "legend-dot", style = paste0("background:", MEDIAN_COLOUR)),
        "Median"
      ),
      div(
        class = "legend-item",
        span(class = "legend-dot", style = paste0("background:", MODE_COLOUR)),
        "Mode"
      ),

      br(),
      actionButton("reset", "Reset to 0,0,0", class = "btn btn-secondary")
    ),

    div(
      class = "right",
      div(
        id = "plotBox",
        plotOutput("plot"),
        br(),
        tags$small(textOutput("stats"))
      )
    )
  )
)

server <- function(input, output, session) {

  # Tighter dynamic height
  plotHeight <- reactive({
    w <- session$clientData$output_plot_width
    if (is.null(w) || !is.finite(w) || w <= 0) {
      w <- 360
    }

    compact <- w < 520
    h_from_w <- if (compact) {
      max(220, 0.40 * w)
    } else {
      max(240, min(480, 0.50 * w))
    }

    vh <- input$vh_px
    if (is.numeric(vh) && is.finite(vh) && vh > 0) {
      cap <- if (compact) 0.44 * vh else 0.48 * vh
      h_from_w <- min(h_from_w, cap)
    }

    round(h_from_w)
  })

  observeEvent(list(plotHeight(), input$resizeTick), {
    session$sendCustomMessage("setSplitHeight", plotHeight())
  }, ignoreInit = FALSE)

  observeEvent(input$reset, {
    updateSliderInput(session, "mean", value = 0)
    updateSliderInput(session, "median", value = 0)
    updateSliderInput(session, "mode", value = 0)
  })

  output$plot <- renderPlot({
    m <- input$mean
    med <- input$median
    mu <- input$mode
    p <- map_params_simple(m, med, mu)

    left_span <- 3 * p$sL
    right_span <- 3 * p$sR
    x_min <- min(-20, mu - left_span)
    x_max <- max(20, mu + right_span)
    pad <- 0.03 * (x_max - x_min)
    x_min <- x_min - pad
    x_max <- x_max + pad

    x <- seq(x_min, x_max, length.out = 1600)
    y <- dsplitnorm(x, p$mu, p$sL, p$sR)

    y_max <- suppressWarnings(max(y, na.rm = TRUE))
    if (!is.finite(y_max) || y_max <= 0) {
      y_max <- 1e-6
    }

    wcd <- session$clientData$output_plot_width
    w_use <- if (is.null(wcd) || !is.finite(wcd) || wcd <= 0) 360 else wcd
    tiny <- w_use < 420

    op <- par(no.readonly = TRUE)
    on.exit(par(op), add = TRUE)

    par(
      bg = OUP_BACKGROUND,
      fg = OUP_TEXT,
      col.axis = OUP_TEXT,
      col.lab = OUP_TEXT,
      col = OUP_TEXT,
      mar = if (tiny) c(2.6, 3.2, 1.4, 0.8) else c(3.6, 4.2, 2.2, 1.0),
      mgp = if (tiny) c(1.9, 0.5, 0) else c(2.5, 0.8, 0),
      xaxs = if (tiny) "i" else "r",
      yaxs = if (tiny) "i" else "r",
      cex.axis = if (tiny) 0.90 else 1.00,
      cex.lab = if (tiny) 0.95 else 1.05
    )

    plot(
      x,
      y,
      type = "n",
      xlab = "",
      ylab = "Density",
      xlim = c(x_min, x_max),
      ylim = c(0, y_max * if (tiny) 1.06 else 1.14),
      axes = TRUE,
      frame.plot = TRUE
    )

    lines(x, y, lwd = 2, col = OUP_TEXT)

    abline(v = m, col = MEAN_COLOUR, lwd = 2)
    abline(v = med, col = MEDIAN_COLOUR, lwd = 2)
    abline(v = mu, col = MODE_COLOUR, lwd = 2)

    usr <- par("usr")
    clamp <- function(z, lo = x_min, hi = x_max) pmin(hi, pmax(lo, z))

    # Place labels in separate vertical lanes whenever their text would overlap.
    label_cex <- if (tiny) 0.85 else 0.95
    label_data <- data.frame(
      x = c(clamp(m), clamp(med), clamp(mu)),
      label = c("Mean", "Median", "Mode"),
      colour = c(MEAN_COLOUR, MEDIAN_COLOUR, MODE_COLOUR),
      stringsAsFactors = FALSE
    )
    label_data <- label_data[order(label_data$x), , drop = FALSE]

    half_width <- vapply(
      label_data$label,
      function(lbl) 0.5 * strwidth(lbl, units = "user", cex = label_cex),
      numeric(1)
    )
    label_data$left <- label_data$x - half_width
    label_data$right <- label_data$x + half_width

    lane_right <- rep(-Inf, 3)
    lane_gap <- 0.012 * diff(usr[1:2])
    label_data$lane <- 1L

    for (i in seq_len(nrow(label_data))) {
      available <- which(label_data$left[i] > lane_right + lane_gap)
      lane <- if (length(available)) available[1] else which.min(lane_right)
      label_data$lane[i] <- lane
      lane_right[lane] <- label_data$right[i]
    }

    lane_drop <- if (tiny) c(0.07, 0.15, 0.23) else c(0.09, 0.17, 0.25)
    label_data$y <- usr[4] - lane_drop[label_data$lane] * diff(usr[3:4])

    for (i in seq_len(nrow(label_data))) {
      text(
        label_data$x[i],
        label_data$y[i],
        label_data$label[i],
        col = label_data$colour[i],
        cex = label_cex
      )
    }
  },
  width = function() {
    w <- session$clientData$output_plot_width
    if (is.null(w) || !is.finite(w) || w <= 0) {
      w <- 360
    }
    round(max(280, min(1100, w)))
  },
  height = function() plotHeight(),
  res = 96,
  execOnResize = TRUE,
  bg = OUP_BACKGROUND
  )

  output$stats <- renderText({
    sprintf(
      "Mean = %.2f   |   Median = %.2f   |   Mode = %.2f",
      input$mean,
      input$median,
      input$mode
    )
  })
}

shinyApp(ui, server)
